 if(b.dataset.rush)act(()=>toggleRestaurantRush(state,Number(b.dataset.rush)));
 if(b.dataset.promo!==undefined)act(()=>launchRestaurantPromo(state,promoChoice.discount,promoChoice.minutes),'Promotion lancée.');
 if(b.dataset.promoStop!==undefined)act(()=>stopRestaurantPromo(state),'Promotion arrêtée.');
