 if(['loan-amount','loan-days'].includes(t.id)){loanChoice[t.id==='loan-amount'?'amount':'days']=Number(t.value);t.blur();lastPanel='';lastPanelAt=0;render();}if(t.id==='promo-discount')promoChoice.discount=Number(t.value);if(t.id==='promo-duration')promoChoice.minutes=Number(t.value);
