function saveStatus(info){saveUi=info;if(!info.ready)state.speed=0;const names={loading:'Chargement…',pending:'À sauvegarder',saving:'Sauvegarde…',saved:'Sauvegardé',error:'Échec de sauvegarde',conflict:'Partie modifiée ailleurs','load-error':'Chargement impossible',offline:'Sauvegardé sur cet appareil'};$('save-status').textContent=info.message||names[info.status];$('save-toggle').title=names[info.status];$('save-toggle').classList.toggle('save-error',['error','conflict','load-error'].includes(info.status));$('save-mode-label').textContent=info.flightMode?'Partie · ✈':'Partie';$('save-flight').textContent=info.flightMode?'Revenir en ligne':'Préparer pour l’avion';$('save-flight').disabled=!info.flightMode&&!info.ready;$('save-local').hidden=info.status!=='conflict';$('save-reload').textContent=info.status==='conflict'?'Reprendre la partie en ligne':'Recharger la sauvegarde';$('save-recovery').hidden=!info.hasRecovery;$('save-previous').disabled=!info.ready||!info.hasPrevious;for(const id of ['save-new','save-now','save-return','save-close','save-export'])$(id).disabled=!info.ready;$('offline-status').textContent=info.ready&&!info.localAvailable?'Sauvegarde locale indisponible sur cet appareil.':offlineMessage;if(['load-error','conflict'].includes(info.status)&&!$('save-dialog').open)$('save-dialog').showModal();}
// Any older game (supermarket v1 or distribution centre v2) is converted: its net worth funds the restaurant and it stays archived.
function toRestaurant(record){if(record.schemaVersion===3)return migrateRestaurantGame(record);let legacyValue=null;if(record.schemaVersion===1){try{legacyValue=stockValuation(structuredClone(record.state)).closingHT;}catch{}}const warehouse=migrateWarehouseGame(record,legacyValue);
 return migrateRestaurantGame({schemaVersion:2,state:warehouse,preferences:record.preferences??{checkoutSound:true}},{warehouseState:warehouse,stockValue:warehouseStats(warehouse).stockValue});}
saveManager=createSaveManager({snapshot:()=>makeSave(state),apply:record=>{const migrated=toRestaurant(record);for(const k of Object.keys(state))delete state[k];Object.assign(state,migrated);lastLogKey=state.log[0]?state.log[0].at+state.log[0].text:'';lastOrderSeen=maxOrderId();lateSeen=lateIds();scene.reset();pendingMinutes=0;lastTime=performance.now();lastPanel='';$('migration-info').hidden=!state.transition;if(state.transition)$('migration-info').textContent=`Ancien centre logistique conservé dans l’export. Capital de départ du restaurant : ${euro(state.initialCash)}${state.transition.debt?' après remboursement de '+euro(state.transition.debt)+' de dette':''}${state.transition.support?' dont '+euro(state.transition.support)+' d’apport de lancement':''}.`;render();},notify:saveStatus});
function resume(){if(saveManager.ready){state.speed=1;saveManager.changed();render();$('save-dialog').close();}}
$('save-toggle').addEventListener('click',()=>{state.speed=0;saveManager.changed();saveManager.flush();$('save-dialog').showModal();});for(const id of ['save-close','save-return'])$(id).addEventListener('click',()=>{$('save-dialog').close();$('warehouse-map').focus();});$('save-dialog').addEventListener('cancel',e=>{if(!saveManager.ready)e.preventDefault();});$('save-now').addEventListener('click',()=>saveManager.flush());$('save-reload').addEventListener('click',async()=>{if(await saveManager.load())resume();});$('save-previous').addEventListener('click',()=>saveManager.load(true));$('save-local').addEventListener('click',async()=>{if(await saveManager.keepLocal())resume();});$('save-recovery').addEventListener('click',async()=>{if(await saveManager.recoverLocal())resume();});$('save-new').addEventListener('click',()=>$('save-confirm').hidden=false);$('save-cancel-new').addEventListener('click',()=>$('save-confirm').hidden=true);$('save-confirm-new').addEventListener('click',async()=>{const fresh=createRestaurantGame();if(state.legacyArchive){fresh.legacyArchive=state.legacyArchive;fresh.transition=state.transition;}if(await saveManager.newGame(makeSave(fresh))){$('save-confirm').hidden=true;resume();}});
$('save-export').addEventListener('click',()=>{const blob=new Blob([JSON.stringify(makeSave(state),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='flux-burger.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
