let lastRender=0;function frame(time){const delta=Math.min(.25,(time-lastTime)/1000);lastTime=time;const elapsedMinutes=saveManager.ready&&!document.querySelector('dialog[open]')?delta*state.speed:0;if(elapsedMinutes){pendingMinutes+=elapsedMinutes;if(pendingMinutes>=1){const minutes=Math.floor(pendingMinutes);pendingMinutes-=minutes;advanceRestaurant(state,minutes);saveManager.changed();}}scene.update(delta,{fraction:pendingMinutes,elapsedMinutes});if(time-lastRender>300){render();lastRender=time;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
