$('save-flight').addEventListener('click',async()=>{$('save-flight').disabled=true;const enabled=!saveManager.flightMode;try{if(enabled){saveManager.changed();await saveManager.flush();if(!saveManager.ready)throw Error('Chargez votre partie avant de préparer le vol.');}await offlineSupport.setFlightMode(enabled);if(!await saveManager.setFlightMode(enabled)){await offlineSupport.setFlightMode(!enabled);return;}if(!enabled){if(saveManager.ready)await saveManager.flush();else if(await saveManager.load())resume();}}catch(error){$('offline-status').textContent=error.message;}finally{$('save-flight').disabled=!saveManager.flightMode&&!saveManager.ready;}});
